import React from "react"
import { FACEBOOK_BLACK } from "../../../assets/colors/Colors"
import IconFacebook from './header-icon-v1-facebook.svg'
import IconGoogle from './header-icon-v1-google.svg'
import IconInstagram from './header-icon-v1-instagram.svg'
import IconPhone from './header-icon-v1-phone.svg'
import IconYelp from './header-icon-v1-yelp.svg'
import GridRow from "../../../locust/composables/GridRow"
import { getFontPoppins } from "../../../assets/fonts/FontPoppins"
import { StackII } from "../../../locust/composables/StackII"
import X from "../../../locust/composables/X"
import Hide from "../../../locust/composables/Hide"


interface HeaderMiniSocial {
    bgc ?: string, 
    phone ?: string,
    facebook ?: string, 
    google ?: string,
    instagram ?: string,
    yelp ?: string,
    textColor ?: string, 
    phoneNumber ?: {
        label : any, 
        value : string,   
    }, 
}

export default ( props : {
    bgc ?: string, 
    phone ?: string,
    facebook ?: string, 
    google ?: string,
    instagram ?: string,
    textColor ?: string, 
    yelp ?: string,
    phoneNumber ?: {
        label : any, 
        value : string,   
    }, 
}) => <HeaderMiniSocialV3 {...props}/>


export const HeaderMiniSocialV3 = ( props : HeaderMiniSocial ) => {
    // this has a non-breaking change so should not actually be a new version.

    const iconPadding : number = 8
    const iff = ( value : any ) => value !== undefined ? true : false
    const Social = ( props :{ href : string, icon : any }) => <GridRow height={45}><a style={{ padding: iconPadding, backgroundColor : '', float : 'right' }} href={`${props.href}`}><img src={props.icon}/></a> </GridRow>
    return (
            
            <div style={{ height : 45, backgroundColor : props.bgc ? props.bgc : FACEBOOK_BLACK  }}>
                { props.phoneNumber && <GridRow height={45}>
                    <div style={{ width : '100vw', backgroundColor : ''}}>
                        <Hide on={720}>
                            <X>
                                <a style={{ color : props.textColor ? props.textColor : 'white', paddingLeft : 20, ...getFontPoppins(), fontWeight : 800, fontSize : 24, textDecoration : 'none'   }} href={`tel:${props.phoneNumber.value}`}> 
                                { props?.phoneNumber?.label }
                                </a>
                            </X>
                        </Hide>
                        <Hide b4={720}>
                            
                            <a style={{ color : props.textColor ? props.textColor : 'white', float : 'left', paddingLeft : 10, ...getFontPoppins(), fontWeight : 800, fontSize : 18, textDecoration : 'none'   }} href={`tel:${props.phoneNumber.value}`}> 
                            { props?.phoneNumber?.label }
                            </a>
                            
                        </Hide>
                    </div>
                </GridRow>}
                <div style={{ position : 'absolute', top : 0, right : 0,  float : 'right', backgroundColor : '', height : '100%', paddingRight : 10 }}>
                    { iff(props.phone) && <Social icon={IconPhone} href={`tel:${props.phone}`}/>}
                    { iff(props.facebook) && <Social icon={IconFacebook} href={`${props.facebook}`}/>}
                    { iff(props.google) && <Social icon={IconGoogle} href={`${props.google}`}/>}
                    { iff(props.instagram) && <Social icon={IconInstagram} href={`${props.instagram}`}/>}
                    { iff(props.yelp) && <Social icon={IconYelp} href={`${props.yelp}`}/>}
                </div>
            </div>
     
        
    )
}